package com.bank.name;

import java.util.*;
import java.util.function.Function;
import java.util.logging.*;

public class MethodRefDemo {
    private static final Logger log = Logger.getLogger("Name");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh"), new Employee("Priya"));
        NameService service = new NameService();

        // both are equivalent
        Function<Employee, String> lambda = e -> e.getName();   // verbose
        Function<Employee, String> ref = Employee::getName;     // concise

        log.info(() -> "via lambda: " + lambda.apply(staff.get(0)));
        log.info(() -> "via ref   : " + ref.apply(staff.get(0)));
        log.info(() -> "names     : " + service.names(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/NameService.java ───
class NameService {
    List<String> names(List<Employee> staff) {
        return staff.stream()
            .map(Employee::getName)     // replaces e -> e.getName()
            .toList();
    }
}
